import {ORGANIZATION_DEPARTMENTS} from '../src/organization.mjs';
import test from 'node:test';
import assert from 'node:assert/strict';
import {WORKFLOWS,buildDocumentPayload,cents,fulfillmentLines,allowedActions,assertAllowedAction,pendingTasks,normalizeSnapshot,renderActions,renderFiles,renderEmpty,safeFileUrl,csvDocument,safeSourceUrl,renderQuoteEvidence,reportFacts,renderBusinessResult,money,statusLabel,weeklyDocumentCounts} from '../src/erp-ui.mjs';
import {mountErp} from '../src/erp.js';

test('eight complete business forms use confirmed workflow IDs',()=>{assert.deepEqual(WORKFLOWS.map(w=>w.id),['project_setup','project_delivery','purchase','sales','stocktake','resource','weekly_report','onboarding']);});
test('project setup and delivery require an existing project and actual evidence',()=>{assert.throws(()=>buildDocumentPayload('project_setup',{title:'立项',objective:'目标'}),/项目/);assert.deepEqual(buildDocumentPayload('project_setup',{title:'客户平台',projectId:'p1',objective:'交付工作台',expectedDate:'2026-12-01'}),{type:'project_setup',title:'客户平台',projectId:'p1',input:{objective:'交付工作台',expectedDate:'2026-12-01'}});assert.throws(()=>buildDocumentPayload('project_delivery',{title:'验收',projectId:'p1',deliveryNote:'完成'}),/验收标准/);assert.equal(buildDocumentPayload('project_delivery',{title:'验收',projectId:'p1',deliveryNote:'交付 3 台设备',acceptanceCriteria:'联调完成'}).input.deliveryNote,'交付 3 台设备');});
test('purchase and sales preserve exact integer cents and positive stock quantities',()=>{for(const type of ['purchase','sales']){const d=buildDocumentPayload(type,{title:'设备',partner:'实际往来单位',projectId:'p1'},[{productId:'pr1',quantity:'3',unitPrice:'19.99'}]);assert.equal(d.lines[0].unitPriceCents,1999);assert.equal(d.lines[0].quantity,3);assert.equal(d.input.partner,'实际往来单位');}assert.throws(()=>buildDocumentPayload('purchase',{title:'设备',partner:'单位'},[{productId:'p',quantity:'0',unitPrice:'1'}]),/数量/);assert.throws(()=>buildDocumentPayload('sales',{title:'设备',partner:'单位'},[{productId:'p',quantity:'1.5',unitPrice:'1'}]),/数量/);});
test('money parsing never rounds invalid extra decimals or floating exponent forms',()=>{assert.equal(cents('0.29'),29);assert.equal(cents('123456.78'),12345678);for(const value of ['1.001','-1','1e4','Infinity','','NaN','90071992547409910'])assert.throws(()=>cents(value));});
test('stocktaking permits actual zero counts, rejects empty and duplicate rows',()=>{assert.equal(buildDocumentPayload('stocktake',{title:'仓库实盘',note:'季度盘点'},[{productId:'p',countedQuantity:'0'}]).lines[0].countedQuantity,0);assert.throws(()=>buildDocumentPayload('stocktake',{title:'盘点',note:'季度盘点'},[{productId:'p',countedQuantity:''}]),/数量/);assert.throws(()=>buildDocumentPayload('stocktake',{title:'盘点',note:'季度盘点'},[{productId:'p',countedQuantity:'0'},{productId:'p',countedQuantity:'1'}]),/合并/);});
test('resource return requires employee and original issue document',()=>{assert.throws(()=>buildDocumentPayload('resource',{title:'归还',operation:'return',purpose:'员工离岗归还',employeeId:'e1'},[{productId:'p',quantity:1}]),/原领用单/);assert.deepEqual(buildDocumentPayload('resource',{title:'归还',operation:'return',purpose:'员工离岗归还',employeeId:'e1',originalDocumentId:'d1'},[{productId:'p',quantity:1}]).input,{operation:'return',purpose:'员工离岗归还',employeeId:'e1',originalDocumentId:'d1'});});
test('weekly report validates date ordering and onboarding requires actual employee role resources',()=>{assert.throws(()=>buildDocumentPayload('weekly_report',{title:'周报',projectId:'p',periodStart:'2026-10-21',periodEnd:'2026-10-20'}),/日期/);assert.equal(buildDocumentPayload('weekly_report',{title:'周报',projectId:'p',periodStart:'2026-10-20',periodEnd:'2026-10-21'}).input.periodEnd,'2026-10-21');assert.throws(()=>buildDocumentPayload('onboarding',{title:'准备',employeeId:'e',position:'研发'}),/资源需求/);assert.equal(buildDocumentPayload('onboarding',{title:'准备',employeeId:'e',position:'研发',resourceRequirements:'笔记本及研发账号'}).input.employeeId,'e');});
test('partial receipt and shipment use completedQuantity and reject over fulfillment',()=>{const doc={lines:[{id:'l1',quantity:5,completedQuantity:3}]};assert.deepEqual(fulfillmentLines(doc,[{lineId:'l1',quantity:'2'}],'receive'),[{lineId:'l1',quantity:2}]);assert.throws(()=>fulfillmentLines(doc,[{lineId:'l1',quantity:'3'}],'ship'),/超过/);assert.throws(()=>fulfillmentLines(doc,[{lineId:'l1',quantity:'0'}],'ship'),/实际办理数量/);assert.throws(()=>fulfillmentLines(doc,[{lineId:'changed',quantity:'1'}],'receive'),/变更/);});
test('actions are always supplied by server and UI does not infer approval from roles',()=>{const d={id:'d',status:'awaiting_approval',allowedActions:['reject']};assert.deepEqual(allowedActions(d).map(a=>a.id),['reject']);assert.throws(()=>assertAllowedAction(d,'approve'),/无权/);assert.doesNotMatch(renderActions(d),/data-operation="approve"/);assert.match(renderActions(d),/退回修改/);assert.equal(allowedActions({status:'awaiting_approval',roles:['admin']}).length,0);});
test('pending tasks distinguish current human work from other employees',()=>{const snap=normalizeSnapshot({tasks:[{id:'1',assigneeId:'me',status:'pending'},{id:'2',assigneeId:'other',status:'pending'},{id:'3',assigneeId:'me',status:'completed'}],documents:[{id:'d',allowedActions:['approve']},{id:'other',allowedActions:[]}]});assert.deepEqual(pendingTasks(snap,'me').tasks.map(t=>t.id),['1']);assert.deepEqual(pendingTasks(snap,'me').approvals.map(t=>t.id),['d']);});
test('business values are escaped and artifact URLs stay within authenticated API paths',()=>{assert.match(renderEmpty('<script>bad</script>'),/&lt;script&gt;/);assert.equal(safeFileUrl('/api/erp/workitems/d/report'),'/api/erp/workitems/d/report');for(const value of ['javascript:alert(1)','https://bad.test/a','//bad.test/a','/api/../secret','/api/runs/a\n'])assert.equal(safeFileUrl(value),'');const html=renderFiles([{name:'<img src=x onerror=1>',url:'javascript:bad()'},{name:'报告',url:'/api/erp/workitems/d/report'}]);assert.doesNotMatch(html,/<img|href="javascript/);assert.match(html,/&lt;img/);assert.match(html,/href="\/api\/erp\/workitems\/d\/report"/);});
test('report CSV retains numeric values and escapes spreadsheet formulas from user text',()=>{const csv=csvDocument(['员工','数量'],[['=HYPERLINK("bad")',3],['  @SUM(1)',-2],['正常,员工',0]]);assert.ok(csv.startsWith('\ufeff'));assert.match(csv,/'=HYPERLINK\(""bad""\)/);assert.match(csv,/'  @SUM/);assert.match(csv,/"-2"/);assert.match(csv,/"正常,员工","0"/);});
test('quote evidence separates real public prices from unconfirmed source pages and escapes every field',()=>{assert.equal(safeSourceUrl('https://supplier.test/config?sku=A'),'https://supplier.test/config?sku=A');for(const value of ['javascript:alert(1)','data:text/html,abc','https://user:password@supplier.test/',' https://supplier.test/','https://supplier.test/\n'])assert.equal(safeSourceUrl(value),'');const html=renderQuoteEvidence({quotes:[{title:'<供应商>',status:'priced',price:1999,currency:'CNY',sourceUrl:'https://supplier.test/config',fetchedAt:'2026-10-20T00:00:00Z',selectedConfiguration:['32GB RAM','1TB SSD'],tax:'未知',warranty:'三年待确认',reason:'税费待核对'},{title:'未公开价格',status:'pending_inquiry',price:null,currency:null,sourceUrl:'javascript:alert(1)',reason:'<script>缺少报价</script>'},{title:'目录页',status:'multiple_price_candidates',price:123,currency:'CNY',sourceUrl:'https://supplier.test/catalog',reason:'同页价格未绑定配置'}]});const [main,pending]=html.split('<details');assert.match(main,/公开标价/);assert.match(main,/1,999 CNY/);assert.match(main,/选定配置：32GB RAM；1TB SSD/);assert.match(main,/税费：未知；保修：三年待确认/);assert.doesNotMatch(main,/未公开价格|目录页|123 CNY/);assert.match(pending,/待确认来源（2）/);assert.match(pending,/待询价/);assert.match(pending,/同页多价，待核对/);assert.match(pending,/https:\/\/supplier.test\/catalog/);assert.match(html,/rel="noopener noreferrer"/);assert.doesNotMatch(html,/供应商报价|pending_inquiry|multiple_price_candidates|href="javascript|<script>|0 币种/);assert.match(html,/&lt;script&gt;/);});
test('quote evidence never promotes numeric candidates or invalid prices when no usable quote was obtained',()=>{const prices=[null,'',NaN,Infinity,-1,true,'0xFF'];const quotes=prices.map((price,i)=>({title:`无效来源${i}`,status:'priced',price,sourceUrl:`https://supplier.test/${i}`}));quotes.push({title:'供应商首页',status:'pending_inquiry',price:99,sourceUrl:'https://supplier.test/',reason:'页面未公开整机价格'},{title:'未知状态来源',status:'failed_internal',price:999});const html=renderQuoteEvidence({quotes});assert.match(html,/尚未取得可用报价/);assert.match(html,/待确认来源（9）/);assert.doesNotMatch(html,/<h3[^>]*>公开标价|99 CNY|failed_internal|NaN|Infinity|供应商报价/);assert.match(html,/供应商首页/);assert.match(html,/页面未公开整机价格/);assert.match(renderQuoteEvidence({quotes:[]}),/尚未取得可用报价/);const mixed=renderBusinessResult({type:'purchase',quoteEvidence:{quotes:[]}});assert.match(mixed,/尚未取得可用报价/);assert.match(renderQuoteEvidence({quotes:[{status:'priced',price:0,currency:'CNY'}]}),/0 CNY/);});

