test('opening workbench is read only, keeps underlying office and restores interaction on close',async()=>{const h=harness();try{await h.mounted.open();assert.equal(h.sibling.inert,false);assert.doesNotMatch(h.root.innerHTML,/erp-rail|erp-nav|虚拟员工协作处理/);assert.equal(h.calls.filter(c=>c.method!=='GET').length,0);assert.match(h.root.innerHTML,/我的工作/);assert.match(h.root.innerHTML,/暂无待办任务/);await h.click('section',{section:'flows'});assert.match(h.root.innerHTML,/项目立项/);assert.match(h.root.innerHTML,/员工岗位与资源/);h.mounted.close();assert.equal(h.sibling.inert,false);assert.equal(h.root.innerHTML,'');}finally{h.cleanup();}});
test('failed mutation retries retain idempotency key and approval uses latest document version',async()=>{let attempted=0;const d={id:'doc1',title:'实际采购',type:'purchase',status:'awaiting_approval',version:7,input:{partner:'供应商'},allowedActions:['approve']};const h=harness(({path,method})=>{if(path==='/api/erp/workitems/doc1')return {document:d,run:{tasks:[]}};if(path==='/api/erp/workitems/doc1/approve'&&method==='POST'){if(++attempted===1)throw new Error('连接中断');return {document:{...d,status:'approved'}};}});try{await h.mounted.open();await h.click('open-document',{id:'doc1'});await h.click('document-action',{id:'doc1',operation:'approve'});const form=h.form('action',{note:'已核对'},{id:'doc1',operation:'approve'});await h.submit(form);assert.equal(h.mounted.state.busy,false);await h.submit(form);const mutations=h.calls.filter(c=>c.path.endsWith('/approve'));assert.equal(mutations.length,2);assert.equal(mutations[0].body.expectedVersion,7);assert.equal(mutations[0].body._requestId,mutations[1].body._requestId);assert.ok(mutations[0].body._requestId);assert.equal(mutations[0].body.note,'已核对');}finally{h.cleanup();}});
test('first use never fabricates products, projects or business records',async()=>{const h=harness();try{await h.mounted.open('products');assert.match(h.root.innerHTML,/暂无产品/);assert.doesNotMatch(h.root.innerHTML,/服务器 A|年度营收|示例公司/);await h.click('new-master',{kind:'project'});assert.match(h.root.innerHTML,/客户/);assert.match(h.root.innerHTML,/项目成员/);assert.match(h.root.innerHTML,/name="ownerId"/);assert.doesNotMatch(h.root.innerHTML,/添加参与项目的业务/);}finally{h.cleanup();}});
test('returned document revision uses same document and never restarts or approves by opening form',async()=>{const d={id:'returned',title:'退回的采购',type:'purchase',projectId:'project1',version:5,status:'rejected',input:{partner:'实际供应商'},lines:[{id:'l',productId:'product1',quantity:2,unitPriceCents:1999}],allowedActions:['revise']};const h=harness(({path})=>path==='/api/erp/workitems/returned'?{document:d}:undefined);try{await h.mounted.open();await h.click('open-document',{id:'returned'});await h.click('document-action',{id:'returned',operation:'revise'});assert.match(h.root.innerHTML,/保存修改/);assert.match(h.root.innerHTML,/data-id="returned"/);assert.match(h.root.innerHTML,/name="projectId"/);assert.doesNotMatch(h.root.innerHTML,/虚拟员工根据本单/);assert.equal(h.calls.filter(c=>c.method!=='GET').length,0);}finally{h.cleanup();}});
test('task submission and acceptance actions follow explicit server rights',async()=>{const h=harness(({path})=>path==='/api/erp/snapshot'?{tasks:[{id:'submitted',title:'交付待验收',assigneeId:'other',status:'submitted',allowedActions:['accept','return']}],currentUser:{id:'me',name:'项目负责人',roles:['project_manager']}}:undefined);try{await h.mounted.open('projects');assert.match(h.root.innerHTML,/待验收/);assert.match(h.root.innerHTML,/验收通过/);assert.match(h.root.innerHTML,/退回补正/);assert.doesNotMatch(h.root.innerHTML,/data-erp-action="task-complete"/);assert.equal(h.calls.filter(c=>c.method!=='GET').length,0);}finally{h.cleanup();}});
test('internal 2D and 3D actions keep the original form DOM, draft and approval version',async()=>{const transitions=[],scene={mode:'2d',async setMode(mode){transitions.push(mode);this.mode=mode;}},d={id:'view-doc',title:'视角切换验收',type:'purchase',status:'awaiting_approval',version:19,input:{partner:'供应商'},allowedActions:['approve']};const h=harness(({path})=>path==='/api/erp/workitems/view-doc'?{document:d}:undefined,{scene});try{await h.mounted.open();await h.click('open-document',{id:d.id});await h.click('document-action',{id:d.id,operation:'approve'});const form=h.form('action',{note:'已核对正式报价，请保留意见。'},{id:d.id,operation:'approve'}),writes=h.root.htmlWrites,calls=h.calls.length;await h.click('view',{mode:'3d'});assert.equal(h.root.currentForm,form);assert.equal(h.root.htmlWrites,writes);assert.equal(form.elements[0].value,'已核对正式报价，请保留意见。');assert.equal(scene.mode,'3d');assert.equal(h.root.viewButtons.length,0);await h.click('view',{mode:'2d'});assert.equal(h.root.currentForm,form);assert.equal(h.root.htmlWrites,writes);assert.equal(h.calls.length,calls);assert.deepEqual(transitions,['3d','2d']);await h.submit(form);const approval=h.calls.find(c=>c.path.endsWith('/approve'));assert.equal(approval.body.expectedVersion,19);assert.equal(approval.body.note,'已核对正式报价，请保留意见。');}finally{h.cleanup();}});
test('resource forms retain actual purpose and confirmed onboarding link, stocktakes require an explanation',()=>{const values={title:'到岗领用',operation:'issue',employeeId:'employee',purpose:'岗位开发设备',sourceOnboardingDocumentId:'approved-onboarding'};const result=buildDocumentPayload('resource',values,[{productId:'laptop',quantity:1}]);assert.equal(result.input.purpose,values.purpose);assert.equal(result.input.sourceOnboardingDocumentId,'approved-onboarding');assert.throws(()=>buildDocumentPayload('resource',{...values,purpose:''},[{productId:'laptop',quantity:1}]),/物品用途/);assert.throws(()=>buildDocumentPayload('stocktake',{title:'盘点'},[{productId:'laptop',countedQuantity:1}]),/盘点原因/);});
test('purchase forms preserve supplier quotation references and reject oversized notes',()=>{const base={title:'采购',partner:'供应商',quotationReference:'正式报价 Q-001',quotationNotes:'含税含运，保修三年'};const result=buildDocumentPayload('purchase',base,[{productId:'server',quantity:2,unitPrice:'3999.99'}]);assert.equal(result.input.quotationReference,'正式报价 Q-001');assert.equal(result.input.quotationNotes,base.quotationNotes);assert.throws(()=>buildDocumentPayload('purchase',{...base,quotationNotes:'a'.repeat(4001)},[{productId:'server',quantity:2,unitPrice:'1'}]),/4000/);});
test('project maintenance updates the existing project and task transfer selects only project members',async()=>{const project={id:'project',name:'在岗交接',customer:'真实客户',ownerId:'me',members:['me','next']},task={id:'task',projectId:'project',title:'待交接任务',assigneeId:'me',status:'pending',allowedActions:['reassign']};const h=harness(({path})=>path==='/api/erp/snapshot'?{projects:[project],tasks:[task],currentUser:{id:'me',roles:['admin']}}:path==='/api/erp/users'?{users:[{id:'me',name:'原负责人',active:true},{id:'next',name:'接替员工',active:true},{id:'outside',name:'非项目人员',active:true}]}:undefined);try{await h.mounted.open('projects');await h.click('edit-project',{id:'project'});assert.match(h.root.innerHTML,/维护项目/);const form=h.form('master',{name:'在岗交接',customer:'真实客户',ownerId:'next'},{kind:'project',id:'project'});await h.submit(form);const change=h.calls.find(c=>c.path==='/api/erp/projects/project'&&c.method==='PUT');assert.ok(change);assert.ok(change.body.members.includes('next'));assert.equal(h.calls.some(c=>c.path==='/api/erp/masterdata'&&c.method==='POST'),false);await h.click('task-reassign',{id:'task'});assert.match(h.root.innerHTML,/接替员工/);assert.doesNotMatch(h.root.innerHTML,/非项目人员/);const transfer=h.form('task-reassign',{assigneeId:'next',note:'原负责人转岗，接替后续工作'},{id:'task'});await h.submit(transfer);assert.equal(h.calls.find(c=>c.path.endsWith('/reassign')).body.note,'原负责人转岗，接替后续工作');}finally{h.cleanup();}});
test('empty personal approval state does not contradict existing completed business',async()=>{const h=harness(({path})=>path==='/api/erp/snapshot'?{documents:[{id:'done',title:'已完成的实际业务',type:'purchase',status:'completed',allowedActions:[]}],currentUser:{id:'me',roles:['admin']}}:undefined);try{await h.mounted.open();assert.match(h.root.innerHTML,/<span>待我审批<\/span><strong>0<\/strong>/);assert.match(h.root.innerHTML,/已完成的实际业务/);assert.doesNotMatch(h.root.innerHTML,/还没有业务单/);}finally{h.cleanup();}});


test('business statuses and server action labels never expose implementation roles',()=>{for(const status of ['draft','agent_running','agent_failed','agent_ready','awaiting_agent'])assert.doesNotMatch(statusLabel(status),/Agent|模型|虚拟员工/i);const html=renderActions({id:'d',allowedActions:[{id:'run_agents',label:'交给虚拟员工'}]});assert.match(html,/提交处理/);assert.doesNotMatch(html,/交给虚拟员工/);});
test('business result puts verified plan and calculation into UI without tool logs or model metadata',()=>{const html=renderBusinessResult({type:'purchase',proposal:{plan:{summary:'采购两台存储服务器',steps:['核对正式报价'],checks:['金额核对一致'],missing:['补充到货日期']},review:{summary:'配置符合需求',checks:['金额核对一致']},calculation:{lines:[{product:'存储服务器',quantity:2,currentStock:0,unitPriceCents:123456,lineTotalCents:246912}],totalCents:246912}}});assert.match(html,/采购两台存储服务器/);assert.match(html,/配置符合需求/);assert.match(html,/¥2,469.12/);assert.match(html,/核对时库存/);assert.match(html,/补充到货日期/);assert.equal(html.split('金额核对一致').length-1,1);assert.doesNotMatch(html,/Agent|虚拟员工|工具调用|模型/);});
test('business result escapes every structured field and never renders model HTML',()=>{const html=renderBusinessResult({proposal:{plan:{summary:'<img onerror=bad>',steps:['<script>bad()</script>'],missing:['<a href=bad>']},review:{summary:'<svg onload=bad>'},calculation:{lines:[{product:'<iframe>',quantity:1,currentStock:0,unitPriceCents:1,lineTotalCents:1}],totalCents:1}}});assert.doesNotMatch(html,/<img|<script|<svg|<iframe|<a href=bad/);assert.match(html,/&lt;img/);assert.match(html,/&lt;iframe/);});
test('report amounts count only approved orders and remain exact beyond aggregate safe integer size',()=>{const facts=reportFacts({documents:[{id:'draft',type:'purchase',status:'draft',lines:[{quantity:1,unitPriceCents:9000000000000000}]},{id:'approved1',type:'purchase',status:'approved',lines:[{quantity:1,unitPriceCents:9000000000000000}]},{id:'approved2',type:'purchase',status:'completed',lines:[{quantity:1,unitPriceCents:9000000000000000}]},{id:'rejected',type:'sales',status:'rejected',lines:[{quantity:1,unitPriceCents:100}]},{id:'sales',type:'sales',status:'partially_shipped',lines:[{quantity:3,unitPriceCents:1999}]}]});assert.equal(facts.purchaseOrderCents,18000000000000000n);assert.equal(money(facts.purchaseOrderCents),'¥180,000,000,000,000.00');assert.equal(facts.salesOrderCents,5997n);assert.equal(facts.confirmedOrders.length,3);assert.equal(facts.completedDocuments.length,1);});
test('reports use accepted task facts, scoped inventory and original loans without invented scores',()=>{const facts=reportFacts({projects:[{id:'p',name:'实际项目'},{id:'empty',name:'未分配任务'}],tasks:[{id:'one',projectId:'p',status:'completed'},{id:'two',projectId:'p',status:'submitted'},{id:'three',projectId:'p',status:'pending'}],products:[{id:'sku',name:'电脑',unit:'台'}],inventory:[{productId:'sku',quantity:6}],movements:[{productId:'sku',delta:10},{productId:'sku',delta:-4}],loans:[{employeeId:'e',productId:'sku',quantity:4,returnedQuantity:1}],performance:[{projectId:'p',documentId:'weekly',periodStart:'2026-10-12',periodEnd:'2026-10-18',facts:{employees:[{employeeId:'e',completedTasks:2}],taskFacts:[{stateAtPeriodEnd:'submitted',assigneeIdAtPeriodEnd:'e'}]}}]});assert.equal(facts.projects[0].completion,33);assert.equal(facts.projects[1].completion,null);assert.equal(facts.products[0].quantity,6);assert.equal(facts.products[0].inQuantity,10);assert.equal(facts.products[0].outQuantity,4);assert.equal(facts.outstandingLoans,3);assert.equal(facts.performance[0].completedTasks,2);assert.equal(facts.performance[0].pendingAcceptanceTasks,1);assert.equal(facts.performance[0].documentId,'weekly');assert.equal('score' in facts.performance[0],false);});
test('single business document exposes result and approval content instead of agent execution detail',async()=>{const doc={id:'result',title:'正式采购',type:'purchase',status:'awaiting_approval',version:3,input:{partner:'供应商'},allowedActions:['approve','reject'],proposal:{plan:{summary:'采购两台服务器',steps:['核对正式报价']},review:{summary:'规格与金额一致'},calculation:{lines:[{product:'服务器',quantity:2,currentStock:0,unitPriceCents:123456,lineTotalCents:246912}],totalCents:246912}},approvals:[{actorName:'王经理',decision:'approved',note:'配置已核对'}]};const h=harness(({path})=>path==='/api/erp/workitems/result'?{document:doc,run:{model:'DO_NOT_RENDER_MODEL',tasks:[{name:'DO_NOT_RENDER_ROLE',goal:'DO_NOT_RENDER_GOAL'}],events:[{message:'DO_NOT_RENDER_LOG'}]}}:undefined);try{await h.mounted.openDocument('result');assert.match(h.root.innerHTML,/采购两台服务器/);assert.match(h.root.innerHTML,/规格与金额一致/);assert.match(h.root.innerHTML,/¥2,469.12/);assert.match(h.root.innerHTML,/王经理/);assert.match(h.root.innerHTML,/data-operation="approve"/);assert.doesNotMatch(h.root.innerHTML,/DO_NOT_RENDER|虚拟员工协作|执行记录|查看进展|产物/);}finally{h.cleanup();}});
test('new submission stays in its document and refresh reveals result in place',async()=>{let completed=false;const base={id:'new-document',type:'project_setup',title:'业务平台立项',status:'draft',version:1,input:{objective:'交付工作台'},projectId:'p',allowedActions:[]};const h=harness(({path,method})=>{if(path==='/api/erp/workitems'&&method==='POST')return{document:base,run:{status:'running'}};if(path==='/api/erp/workitems/new-document')return{document:{...base,status:completed?'awaiting_approval':'draft',agentStatus:completed?'completed':'running',proposal:completed?{plan:{summary:'工作台项目范围已确认',steps:['完成接口联调']},review:{summary:'交付标准清晰'}}:null},run:{status:completed?'completed':'running'}};});try{await h.mounted.open('flows');await h.click('new-document',{type:'project_setup'});const form=h.form('document',{title:'业务平台立项',projectId:'p',objective:'交付工作台'},{type:'project_setup'});await h.submit(form);assert.equal(h.mounted.state.section,'detail');assert.match(h.root.innerHTML,/处理中/);completed=true;await h.mounted.refresh();assert.match(h.root.innerHTML,/工作台项目范围已确认/);assert.match(h.root.innerHTML,/完成接口联调/);assert.equal(h.calls.filter(c=>c.path==='/api/erp/workitems'&&c.method==='POST').length,1);assert.doesNotMatch(h.root.innerHTML,/查看进展|工具调用/);}finally{h.cleanup();}});
test('person selection opens employee context and navigation remains synchronized with bottom bar',async()=>{const events=[],h=harness(({path})=>path==='/api/erp/users'?{users:[{id:'e',name:'李明',department:'业务部',title:'项目经理',roles:['project_manager']},{id:'other',name:'其他员工'}]}:path==='/api/erp/snapshot'?{currentUser:{id:'me',roles:['admin']},tasks:[{id:'mine',assigneeId:'e',status:'pending',title:'完成现场验收'},{id:'other',assigneeId:'other',status:'pending',title:'不要显示的任务'}]}:undefined,{onNavigate:value=>events.push(value)});try{await h.mounted.openPerson('e');assert.match(h.root.innerHTML,/李明/);assert.match(h.root.innerHTML,/完成现场验收/);assert.doesNotMatch(h.root.innerHTML,/不要显示的任务/);assert.equal(events.at(-1).section,'people');assert.equal(events.at(-1).opened,true);await h.mounted.open('reports');assert.equal(events.at(-1).section,'reports');assert.equal(h.sibling.inert,false);h.mounted.close();assert.equal(events.at(-1).opened,false);}finally{h.cleanup();}});

test('weekly approval includes frozen employee and accepted task evidence before posting',async()=>{const doc={id:'week',type:'weekly_report',title:'十月第三周',status:'awaiting_approval',version:4,input:{periodStart:'2026-10-12',periodEnd:'2026-10-18',facts:{completedTasks:1,submittedTasks:2,pendingTasks:1,overdueTasks:0,employees:[{employeeId:'employee',assignedTasks:2,submittedTasks:2,completedTasks:1,pendingTasks:1,overdueTasks:0,acceptedDeliveries:0}],tasks:[{title:'交付客户清单',employeeId:'employee',acceptedBy:'reviewer',completedAt:'2026-10-18T09:00:00Z'}],taskFacts:[{title:'待验收材料',assigneeIdAtPeriodEnd:'employee',stateAtPeriodEnd:'submitted'}],basis:'INTERNAL_BASIS_DO_NOT_PRINT'}},allowedActions:['approve']};const h=harness(({path})=>path==='/api/erp/workitems/week'?{document:doc}:path==='/api/erp/users'?{users:[{id:'employee',name:'李明'},{id:'reviewer',name:'王经理'}]}:undefined);try{await h.mounted.openDocument('week');assert.match(h.root.innerHTML,/本期工作记录/);assert.match(h.root.innerHTML,/交付客户清单/);assert.match(h.root.innerHTML,/王经理/);assert.match(h.root.innerHTML,/待验收材料/);assert.match(h.root.innerHTML,/期末未结/);assert.doesNotMatch(h.root.innerHTML,/已确认工作记录|INTERNAL_BASIS|scoresAssigned|timezone/);assert.equal(h.calls.filter(c=>c.method!=='GET').length,0);}finally{h.cleanup();}});
test('completed work exposes delivery text and evidence directly in the task row',async()=>{const h=harness(({path})=>path==='/api/erp/snapshot'?{tasks:[{id:'task',title:'客户部署',assigneeId:'me',status:'completed',result:'客户平台已部署并通过联调',evidence:[{reference:'交付编号 DEP-009'}],allowedActions:[]}],currentUser:{id:'me',roles:['employee']}}:undefined);try{await h.mounted.open('projects');assert.match(h.root.innerHTML,/客户平台已部署并通过联调/);assert.match(h.root.innerHTML,/交付编号 DEP-009/);assert.match(h.root.innerHTML,/已验收/);assert.doesNotMatch(h.root.innerHTML,/data-erp-action="task-complete"/);}finally{h.cleanup();}});
test('saved revision starts processing exactly once and a processing failure does not resubmit the revision',async()=>{let doc={id:'rev',title:'立项',type:'project_setup',status:'rejected',projectId:'p',version:8,input:{objective:'客户办公平台'},allowedActions:['revise']};const h=harness(({path,method})=>{if(path==='/api/erp/workitems/rev')return{document:doc};if(path==='/api/erp/workitems/rev/revise'&&method==='POST'){doc={...doc,status:'draft',version:9,allowedActions:['run_agents','revise']};return{document:doc};}if(path==='/api/erp/workitems/rev/run_agents')throw new Error('模型暂时不可用');});try{await h.mounted.openDocument('rev');await h.click('document-action',{operation:'revise'});const form=h.form('document',{title:'立项',projectId:'p',objective:'客户办公平台'},{type:'project_setup',id:'rev'});await h.submit(form);const revision=h.calls.filter(c=>c.path.endsWith('/revise'));const runs=h.calls.filter(c=>c.path.endsWith('/run_agents'));assert.equal(revision.length,1);assert.equal(runs.length,1);assert.equal(revision[0].body.expectedVersion,8);assert.equal(runs[0].body.expectedVersion,9);assert.equal(h.mounted.state.section,'detail');assert.doesNotMatch(h.root.innerHTML,/data-erp-form="document"/);assert.match(h.root.innerHTML,/data-operation="run_agents"/);}finally{h.cleanup();}});
test('ordinary employee does not get restricted master-data and stocktake creation controls',async()=>{const h=harness(({path})=>path==='/api/erp/snapshot'?{currentUser:{id:'me',roles:['employee']},projects:[{id:'p',name:'参与项目',ownerId:'other',members:['me','other']}] }:undefined);try{await h.mounted.open('flows');assert.doesNotMatch(h.root.innerHTML,/data-type="stocktake"|data-type="onboarding"/);await h.mounted.open('inventory');assert.doesNotMatch(h.root.innerHTML,/data-type="stocktake"/);await h.mounted.open('products');assert.doesNotMatch(h.root.innerHTML,/data-erp-action="new-master"/);await h.mounted.open('projects');assert.doesNotMatch(h.root.innerHTML,/data-erp-action="new-master"|data-erp-action="new-task"/);}finally{h.cleanup();}});
test('task creation only offers members of the selected project',async()=>{const h=harness(({path})=>path==='/api/erp/snapshot'?{currentUser:{id:'me',roles:['admin']},projects:[{id:'p',name:'实际项目',ownerId:'me',members:['me','member']}] }:path==='/api/erp/users'?{users:[{id:'me',name:'负责人'},{id:'member',name:'项目同事'},{id:'outsider',name:'项目外人员'}]}:undefined);try{await h.mounted.open('projects');await h.click('new-task',{id:'p'});assert.match(h.root.innerHTML,/项目同事/);assert.doesNotMatch(h.root.innerHTML,/项目外人员/);}finally{h.cleanup();}});
test('stocktaking result states book count and difference rather than requiring users to infer them',()=>{const html=renderBusinessResult({type:'stocktake',proposal:{calculation:{lines:[{product:'电脑',quantity:4,countedQuantity:4,currentStock:6,bookQuantity:6,difference:-2,unitPriceCents:10000,lineTotalCents:40000}],totalCents:40000}}});assert.match(html,/账面数量/);assert.match(html,/差异/);assert.match(html,/<td>-2<\/td>/);assert.match(html,/colspan="6"/);});

test('changing password signals the office shell through a bubbling event and clears the form',async()=>{const events=[],h=harness(undefined,{onEvent:event=>events.push(event)});try{await h.mounted.open('people');await h.click('password');let cleared=false;const form=h.form('password',{currentPassword:'Current-pass-998',newPassword:'Fresh-password-996',confirmPassword:'Fresh-password-996'});form.reset=()=>{cleared=true;};await h.submit(form);assert.equal(cleared,true);assert.equal(h.mounted.isOpen,false);assert.equal(events.length,1);assert.equal(events[0].type,'office:session-ended');assert.equal(events[0].bubbles,true);assert.equal(h.calls.filter(c=>c.path==='/api/erp/identity/password'&&c.method==='POST').length,1);}finally{h.cleanup();}});

test('a late submission result does not replace another business form opened from the dock',async()=>{let resolveMutation;const doc={id:'late',type:'project_setup',title:'先提交的立项',status:'draft',version:1,allowedActions:[]};const h=harness(({path,method})=>path==='/api/erp/workitems'&&method==='POST'?new Promise(resolve=>{resolveMutation=resolve;}):undefined);try{await h.mounted.open('flows');await h.click('new-document',{type:'project_setup'});const first=h.form('document',{title:'先提交的立项',projectId:'p',objective:'交付客户平台'},{type:'project_setup'});const pending=h.submit(first);assert.equal(typeof resolveMutation,'function');await h.mounted.open('projects',{mode:'create',kind:'project'});const next=h.form('master',{name:'正在填写的新项目',customer:'新客户',ownerId:'me'},{kind:'project'});h.root.listeners.input();const writes=h.root.htmlWrites;resolveMutation({document:doc,run:{status:'running'}});await pending;assert.equal(h.mounted.state.section,'projects');assert.equal(h.mounted.state.mode,'create');assert.equal(h.root.currentForm,next);assert.equal(h.root.htmlWrites,writes);assert.equal(next.elements.find(f=>f.name==='name').value,'正在填写的新项目');assert.equal(h.calls.some(c=>c.path==='/api/erp/workitems/late'),false);assert.equal(h.mounted.state.busy,false);}finally{h.cleanup();}});

test('dock module changes capture a form without input events and restore its complete draft without submitting',async()=>{const h=harness(({path})=>path==='/api/erp/snapshot'?{projects:[{id:'project-draft',name:'实际项目',status:'draft'}],currentUser:{id:'me',roles:['admin']}}:undefined,{domForms:true});try{await h.mounted.open('flows');await h.click('new-document',{type:'project_setup'});const values={title:'客户 <工作台> 立项',projectId:'project-draft',objective:'保留范围、接口与验收条件',expectedDate:'2026-12-15'};for(const field of h.root.currentForm.elements)if(field.name in values)field.value=values[field.name];await h.mounted.open('reports');await h.mounted.open('flows');await h.click('new-document',{type:'project_setup'});const restored=Object.fromEntries(h.root.currentForm.elements.map(field=>[field.name,field.value]));for(const [name,value]of Object.entries(values))assert.equal(restored[name],value,name);assert.equal(h.calls.filter(call=>call.method!=='GET').length,0);}finally{h.cleanup();}});
test('destroy on sign-out clears draft and private work state before a new office session',async()=>{const h=harness(({path})=>path==='/api/erp/snapshot'?{projects:[{id:'secret-project',name:'前一账号项目',status:'draft'}],documents:[{id:'secret-document',title:'前一账号单据'}],currentUser:{id:'me',roles:['admin']}}:undefined,{domForms:true});let next;try{await h.mounted.open('flows');await h.click('new-document',{type:'project_setup'});for(const field of h.root.currentForm.elements)if(field.name==='title')field.value='前一账号未提交草稿';h.mounted.destroy();assert.equal(h.mounted.state.snapshot.documents.length,0);assert.equal(h.mounted.state.snapshot.projects.length,0);assert.equal(h.root.innerHTML,'');next=mountErp({request:async path=>path==='/api/erp/snapshot'?{currentUser:{id:'next',roles:['admin']},projects:[{id:'next-project',name:'下一账号待立项项目',status:'draft'}]}:path==='/api/erp/users'?{users:[]}:{},session:{actor:{id:'next',roles:['admin']}},container:document.body});await next.open('flows');await h.click('new-document',{type:'project_setup'});assert.equal(h.root.currentForm.elements.find(field=>field.name==='title').value,'');assert.doesNotMatch(h.root.innerHTML,/前一账号/);}finally{next?.destroy();h.cleanup();}});

test('weekly report shows actual document count and distinct business types as separate facts',async()=>{const documents=['project_setup','purchase','sales','resource','resource','stocktake','project_delivery'].map((type,index)=>({id:'business-'+index,type})),facts={businessDocuments:documents,employees:[],taskFacts:[]},doc={id:'week-counts',type:'weekly_report',title:'项目本期周报',status:'awaiting_approval',input:{facts},allowedActions:[]};assert.deepEqual(weeklyDocumentCounts(facts),{documentCount:7,typeCount:6});const h=harness(({path})=>path==='/api/erp/workitems/week-counts'?{document:doc}:undefined);try{await h.mounted.openDocument('week-counts');assert.match(h.root.innerHTML,/7份业务单据/);assert.match(h.root.innerHTML,/6种业务类型/);assert.doesNotMatch(h.root.innerHTML,/7种业务类型|typeCount|documentCount/);}finally{h.cleanup();}});
