test('silent refresh preserves unchanged content and scroll position, and new views start at the top',async()=>{
 const docs={first:{id:'first',type:'purchase',title:'长采购单',status:'awaiting_approval',input:{partner:'供应商'},proposal:{plan:{summary:'采购核对内容'}},allowedActions:[]},second:{id:'second',type:'sales',title:'另一业务单',status:'draft',input:{partner:'客户'},allowedActions:[]}};
 const h=harness(({path})=>path.startsWith('/api/erp/workitems/')?{document:docs[path.split('/').at(-1)]}:undefined);
 try{
  await h.mounted.openDocument('first');const original=h.root.querySelector('[data-erp-content]');original.scrollTop=936;original.scrollLeft=14;
  await h.mounted.refresh({silent:true});const refreshed=h.root.querySelector('[data-erp-content]');assert.equal(refreshed,original,'unchanged polling retains the original DOM');assert.equal(refreshed.scrollTop,936);assert.equal(refreshed.scrollLeft,14);
  await h.mounted.openDocument('second');assert.equal(h.root.querySelector('[data-erp-content]').scrollTop,0);
  h.root.querySelector('[data-erp-content]').scrollTop=410;await h.mounted.open('reports');assert.equal(h.root.querySelector('[data-erp-content]').scrollTop,0);
  h.root.querySelector('[data-erp-content]').scrollTop=520;await h.click('report-tab',{tab:'stock'});assert.equal(h.root.querySelector('[data-erp-content]').scrollTop,0);
  h.root.querySelector('[data-erp-content]').scrollTop=330;await h.mounted.refresh({silent:true});assert.equal(h.root.querySelector('[data-erp-content]').scrollTop,330);
  h.mounted.close();await h.mounted.open('reports');assert.equal(h.root.querySelector('[data-erp-content]').scrollTop,0);assert.equal(h.calls.filter(call=>call.method!=='GET').length,0);
 }finally{h.cleanup();}
});

