test('successful POST and PUT changes read a new snapshot and fence out the pending pre-write poll',async()=>{
 for(const kind of ['product-create','project-update','document-post']){
  const old=deferredResponse();let reads=0,saved=false;
  const record={id:'p',name:'原项目',customer:'客户',ownerId:'me',members:['me'],status:'active'},documentRecord={id:'business',type:'project_delivery',title:'项目交付',status:'approved',version:2,input:{},allowedActions:['post']};
  const data=()=>({currentUser:{id:'me',roles:['admin']},products:saved&&kind==='product-create'?[{id:'saved',name:'刚保存的服务器',sku:'new'}]:[],projects:[{...record,name:saved?'刚保存的项目':'原项目'}],documents:[{...documentRecord,status:saved?'completed':'approved'}]});
  const h=harness(({path,method})=>{
   if(path==='/api/erp/snapshot')return ++reads===2?old.promise:data();
   if(path==='/api/erp/workitems/business')return {document:{...documentRecord,status:saved?'completed':'approved',allowedActions:saved?[]:['post'],...(saved?{confirmation:{reference:'DEL-ACTUAL',note:'已核对交付',actorName:'实际负责人'}}:{})}};
   if(method==='POST'&&path==='/api/erp/masterdata'||method==='PUT'&&path==='/api/erp/projects/p'||method==='POST'&&path==='/api/erp/workitems/business/post'){saved=true;return {ok:true};}
  });
  try{
   let form;
   if(kind==='product-create'){await h.mounted.open('products');await h.click('new-master',{kind:'product'});form=h.form('master',{name:'刚保存的服务器',sku:'new',unit:'台',price:'10'},{kind:'product'});}
   else if(kind==='project-update'){await h.mounted.open('projects');await h.click('edit-project',{id:'p'});form=h.form('master',{name:'刚保存的项目',customer:'客户',ownerId:'me'},{kind:'project',id:'p'});}
   else{await h.mounted.openDocument('business');await h.click('document-action',{operation:'post'});form=h.form('action',{reference:'DEL-ACTUAL',note:'已核对交付'},{id:'business',operation:'post'});}
   const poll=h.mounted.refresh({silent:true});assert.equal(reads,2);await h.submit(form);assert.equal(reads,3,'A successful write must not reuse its pre-write snapshot request.');
   if(kind==='product-create')assert.match(h.root.innerHTML,/刚保存的服务器/);else if(kind==='project-update')assert.match(h.root.innerHTML,/刚保存的项目/);else{assert.match(h.root.innerHTML,/DEL-ACTUAL/);assert.equal(h.mounted.state.snapshot.documents[0].status,'completed');}
   const writes=h.root.htmlWrites;old.resolve({currentUser:{id:'me',roles:['admin']},products:[],projects:[record],documents:[documentRecord]});await poll;assert.equal(h.root.htmlWrites,writes,'The pre-write response must not replace the confirmed result.');assert.equal(h.calls.filter(call=>call.method!=='GET').length,1);
  }finally{h.cleanup();}
 }
});


